@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('ledgerDirection');const targets=document.querySelectorAll('.transfer-only');function update(){targets.forEach(el=>{el.hidden=select.value!=='transfer';const control=el.querySelector('select');if(control){control.required=select.value==='transfer';if(!control.required)control.value='';}})}if(select){select.addEventListener('change',update);update();}});</script>@endpush
